import json
import logging
from abc import ABC, abstractmethod
from robot.libraries.BuiltIn import BuiltIn
from taf.rfrl.common_resources.ee_kpi.ee_variant_generator import EEVariantGenerator
from taf.rfrl.common_resources.ee_kpi.exceptions import MissingKpiName


def calculate_avg(values):
    return sum(values) / float(len(values))


class GenericReportEEKpi(ABC):
    KPI_ID_MAPPING = {}
    CELL_RAT_MAPPING = {
        "GNCEL": "2G",
        "WNCEL": "3G",
        "LNCEL": "4G",
        "NRCELL": "5G",
    }

    COUNTERS_CONFIG_PARAMS = {
        'System': {
            'description': 'SBTS_Energy_Consumption',
            'counters': {
                'M40002C0': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40002C1': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40002C2': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
            }
        },
        'SM': {
            'description': 'SBTS_SM_Energy_Monitoring',
            'counters': {
                'M40004C0': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40004C1': {'calculation_method': min, 'unit_multiplier': 1},
                'M40004C2': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40004C3': {'calculation_method': max, 'unit_multiplier': 1},
            }
        },
        'BBMOD': {
            'description': 'SBTS_BBMOD_Energy_Monitoring',
            'counters': {
                'M40028C0': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40028C1': {'calculation_method': min, 'unit_multiplier': 1},
                'M40028C2': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40028C3': {'calculation_method': max, 'unit_multiplier': 1},
            }
        },
        'RFM': {
            'description': 'SBTS_RFM_Energy_Monitoring',
            'counters': {
                'M40003C2': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40003C3': {'calculation_method': min, 'unit_multiplier': 1},
                'M40003C4': {'calculation_method': calculate_avg, 'unit_multiplier': 1},
                'M40003C5': {'calculation_method': max, 'unit_multiplier': 1},
            }
        }
    }

    def __init__(self):
        self._all_cells_info = None
        self._passed_cell_dn_type = None

    def prepare_kpi_structure(self, counters_before, counters_after, variants, additinal_params, ee_kpi_targets=None,
                              required_intervals=4, pm_interval=900):
        all_kpi_structure = []
        for dist_name in variants:
            kpi_structure = self._prepare_structure_for_each_counter_under_dist_name(counters_before, counters_after,
                                                                                     dist_name,
                                                                                     variants[dist_name],
                                                                                     additinal_params,
                                                                                     ee_kpi_targets,
                                                                                     required_intervals,
                                                                                     pm_interval)
            all_kpi_structure.extend(kpi_structure)
        return all_kpi_structure

    def _prepare_structure_for_each_counter_under_dist_name(self, counters_before, counters_after, dist_name,
                                                            variant, additinal_params, ee_kpi_targets=None,
                                                            required_intervals=4, pm_interval=900):
        if 'RMOD' in dist_name:
            counter_config_params = GenericReportEEKpi.COUNTERS_CONFIG_PARAMS['RFM']
        elif 'BBMOD' in dist_name:
            counter_config_params = GenericReportEEKpi.COUNTERS_CONFIG_PARAMS['BBMOD']
        elif 'SMOD' in dist_name:
            counter_config_params = GenericReportEEKpi.COUNTERS_CONFIG_PARAMS['SM']
        else:
            counter_config_params = GenericReportEEKpi.COUNTERS_CONFIG_PARAMS['System']

        kpi_structure = []
        collected_counters = self._extract_counter_ids(counters_before)
        for counter_name in counter_config_params['counters']:
            if counter_name not in collected_counters:
                logging.debug(f"Counter {counter_name} not found in collected counters. Skipping calculation")
                continue
            kpi_value = self._calculate_value_for_single_counter(
                counters_before, counters_after, dist_name,
                counter_name, counter_config_params['description'],
                counter_config_params['counters'][counter_name]['calculation_method'],
                counter_config_params['counters'][counter_name]['unit_multiplier'],
                required_intervals=required_intervals, pm_interval=pm_interval
            )
            if kpi_value is None:
                logging.debug(f"Skipping KPI structure preparation for {counter_name} and dist_name {dist_name}")
                continue

            structure = self._prepare_single_kpi_structure(kpi_value, counter_name, variant,
                                                           additinal_params, ee_kpi_targets)
            kpi_structure.append(structure)
        return kpi_structure

    @abstractmethod
    def _prepare_single_kpi_structure(self, pi_value, counter_name, variant, additinal_params, ee_kpi_targets):
        pass

    @staticmethod
    def _calculate_value_for_single_counter(counters_before, counters_after, dist_name, counter_name, description,
                                            calculation_method, unit_multiplier=1, required_intervals=4,
                                            pm_interval=900):

        try:
            before_value = GenericReportEEKpi._get_counters_based_on_dist_name(counters_before, dist_name,
                                                                               description, counter_name)
        except KeyError as e:
            logging.debug(f"Counter {counter_name} not found for {dist_name}. "
                          f"Probably is not supported for this HW. Details {e}")
            return None
        after_value = GenericReportEEKpi._get_counters_based_on_dist_name(counters_after, dist_name,
                                                                          description, counter_name)

        added_pm_periods = list(after_value.keys() - before_value.keys())
        number_of_intervals = len(added_pm_periods)
        number_of_intervals_to_calculate = number_of_intervals - 1  # skip first interval
        if number_of_intervals < required_intervals:
            raise ValueError(f"Required at least {required_intervals} PM periods(got {number_of_intervals}) between "
                             f"counters collected after and before running Test Model for {dist_name}")

        added_pm_periods.sort()
        pm_periods_for_calculation = added_pm_periods[-number_of_intervals_to_calculate:]
        time_diff = int(pm_periods_for_calculation[-1]) - int(pm_periods_for_calculation[0])
        total_time_diff = time_diff + pm_interval
        if total_time_diff < required_intervals * pm_interval:
            raise ValueError(
                f"To calculate the average, minimum {required_intervals} full {pm_interval}-seconds periods are"
                f"needed, but the total time for the {number_of_intervals} periods "
                f"is {total_time_diff} seconds for {dist_name}.")

        pm_values_for_calculation = [after_value[pm_period] for pm_period in pm_periods_for_calculation]

        value = calculation_method(pm_values_for_calculation)
        value = value * unit_multiplier
        return value

    @staticmethod
    def _extract_counter_ids(collected_counters):
        counter_ids = []

        def check_if_int(value):
            try:
                int(value)
                return True
            except ValueError:
                return False

        def recursive_search(d):
            if isinstance(d, dict):
                for key, value in d.items():
                    if isinstance(value, dict) and check_if_int(list(value.keys())[0]):
                        counter_ids.append(key)
                    recursive_search(value)

        recursive_search(collected_counters)
        return counter_ids

    @staticmethod
    def _get_counters_based_on_dist_name(counters, dist_name, description, counter_name):
        wanted_counters = counters['BTS']
        for dn_part in dist_name.split('/'):
            wanted_counters = wanted_counters[dn_part]

        return wanted_counters[description][counter_name]

    @staticmethod
    def _get_all_runtime_cells(bts_info):
        all_cells = []
        for rat in bts_info['cells']:
            for cell in bts_info['cells'][rat]:
                all_cells.append(cell['id']['internal'])
        return all_cells

    @staticmethod
    def _get_rat_from_cells(cells):
        rat = set()
        for mapping in GenericReportEEKpi.CELL_RAT_MAPPING:
            for cell in cells:
                if mapping in cell:
                    rat.add(GenericReportEEKpi.CELL_RAT_MAPPING[mapping])
                    break
        return sorted(list(rat))

    @staticmethod
    def _get_kpi_name(counter_name, postfix):
        kpi_name = counter_name.upper() + '_' + postfix
        return kpi_name

    def _get_kpi_id(self, counter_name, postfix):
        # proper KPI ID you can find in
        # https://nokia.sharepoint.com/sites/SRANOSPDZLT/Shared%20Documents/EE_KPI_Source.csv
        kpi_name = GenericReportEEKpi._get_kpi_name(counter_name, postfix)
        kpi_id = type(self).KPI_ID_MAPPING.get(kpi_name)
        if kpi_id is None:
            raise MissingKpiName(f"Missing KPI_NAME: '{kpi_name}' in {type(self)}.KPI_ID_MAPPING.\n"
                                 f"Please check if '{kpi_name}' is not defined or provided kpi_name is wrong")
        kpi_padded = str(kpi_id).zfill(5)
        return kpi_padded

    @staticmethod
    def _get_kpi_target(ee_kpi_targets, counter_name, postfix):
        kpi_name = GenericReportEEKpi._get_kpi_name(counter_name, postfix)
        if ee_kpi_targets:
            return ee_kpi_targets.get(kpi_name)

    @staticmethod
    def _report_single_kpi(**kwargs):
        robot_args = []
        for raw_param in kwargs:
            raw_value = kwargs[raw_param]
            param = 'kpi_id' if raw_param == 'id' else raw_param
            if raw_param == 'variant':
                value = json.dumps(raw_value)
            elif raw_param == 'value' and isinstance(raw_value, (int, float)):
                value = "{:.2f}".format(raw_value)
            else:
                value = raw_value

            robot_args.append('{}={}'.format(param, value))
        GenericReportEEKpi._import_taf_sw_reporting_portal()
        BuiltIn().run_keyword('taf.sw.reporting_portal.report_kpi_results', *robot_args)

    @staticmethod
    def _import_taf_sw_reporting_portal():
        lib_name = 'taf.sw.reporting_portal'
        all_libraries = BuiltIn().get_library_instance(all=True)
        if lib_name not in all_libraries:
            logging.debug("Importing {}".format(lib_name))
            BuiltIn().import_library(lib_name)


