    def report_ee_kpi(self, ee_counters_before, ee_counters_after, test_model_params, detailed_bts_info,
                      ee_kpi_targets=None, check_load_type=True, required_intervals=4, pm_interval=900):
        """
        Report EE KPI to ReP. Results are presented in ReP under link:
            https://rep-portal.wroclaw.nsn-rdnet.net/reports/kpi/

        :param ee_counters_before: Counters collected by get_ee_counters before running Test Model
        :param ee_counters_after: Counters collected by get_ee_counters after running Test Model
        :param test_model_params: list of dicts (or single dict) of Test Model parameters. should contain at least:
                test_model_params = [
                            {
                             'dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-0',
                             'test_model': 'NR-FR1-TM1.1.ETSI',
                             'p_max': 17,
                             'load_type': 'slotWiseLoad',
                             'load_level': 'load_70',
                             'load_level_name': 'Full'
                            },
                            {
                             'dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1',
                             'test_model': 'NR-FR1-TM1.1.ETSI',
                             'p_max': 21,
                             'load_type': 'slotWiseLoad',
                             'load_level': 'load_70',
                             'load_level_name': 'Full'
                            },
                            .....
                ]
        :param detailed_bts_info: results of 'get_detailed_bts_info' method(taf.rfrl.common_resources.ee_kpi.interface).
        :param ee_kpi_targets: dict with KPI targets eg.
                ee_kpi_targets = {
                    'M40004C2_Idle': 100,
                    'M40004C2_Low': 30,
                }
        :param check_load_type: check if load_type is the same for all test_model_params
        :param required_intervals: number of PM intervals to calculate KPI value
        :param pm_interval: PM interval in seconds, default is 900 seconds(15 minutes)
        :return: list of dicts with KPI results(in the same format which is visible in ReP JSON file)
        """
        test_model_params = test_model_params if isinstance(test_model_params, list) else [test_model_params]
        prepared_kpi = self.prepare_ee_kpi(ee_counters_before, ee_counters_after, test_model_params, detailed_bts_info,
                                           ee_kpi_targets, check_load_type, required_intervals, pm_interval)
        for single_kpi_params in prepared_kpi:
            GenericReportEEKpi._report_single_kpi(**single_kpi_params)
        return prepared_kpi

    def prepare_ee_kpi(self, ee_counters_before, ee_counters_after, test_model_params, detailed_bts_info,
                       ee_kpi_targets=None, check_load_type=True, required_intervals=4, pm_interval=900):
        """
        Just prepare KPI structure without reporting it to ReP and return list of dicts
        with KPI results(in the same format as seen in ReP JSON file)

        :param ee_counters_before: Counters collected by get_ee_counters before running Test Model
        :param ee_counters_after: Counters collected by get_ee_counters after running Test Model
        :param test_model_params: list of dicts of Test Model parameters. should contain at least:
                test_model_params = [
                            {
                             'dist_name': 'MRBTS-78034/NRBTS-78034/NRCELL-0',
                             'test_model': 'NR-FR1-TM1.1.ETSI',
                             'p_max': 17,
                             'load_type': 'slotWiseLoad',
                             'load_level': 'load_70'
                            },
                            {
                             'dist_name': 'MRBTS-78034/NRBTS-78034/NRCELL-1',
                             'test_model': 'NR-FR1-TM1.1.ETSI',
                             'p_max': 21,
                             'load_type': 'slotWiseLoad',
                             'load_level': 'load_70'
                            },
                            .....
                ]
        :param detailed_bts_info: results of 'get_detailed_bts_info' method(taf.rfrl.common_resources.ee_kpi.interface).
        :param ee_kpi_targets: dict with KPI targets eg.
                ee_kpi_targets = {
                    'M40004C2_Idle': 100,
                    'M40004C2_Low': 30,
                }
        :param check_load_type: check if load_type is the same for all test_model_params
        :param required_intervals: number of PM intervals to calculate KPI value
        :param pm_interval: PM interval in seconds, default is 900 seconds(15 minutes)
        :return: list of dicts with KPI results(in the same format as seen in ReP JSON file)
        """

        if check_load_type:
            load = [record['load_level'] for record in test_model_params]
            set_load = set(load)
            if len(set_load) > 1:
                raise ValueError("Different load types in test_model_params")

        used_cell = [record['dist_name'] for record in test_model_params]
        evg = EEVariantGenerator(detailed_bts_info, used_cell)
        evg.prepare_variants_to_report()
        self._all_cells_info = evg.all_cells_info
        self._passed_cell_dn_type = evg._passed_cell_dn_type

        all_kpi = []
        for kpi_variant in [evg.system_variant, evg.smod_variant, evg.bbmod_variant, evg.rf_variant]:
            all_kpi.extend(self.prepare_kpi_structure(ee_counters_before, ee_counters_after,
                                                      kpi_variant, test_model_params, ee_kpi_targets,
                                                      required_intervals, pm_interval))
        return all_kpi

    def _prepare_single_kpi_structure(self, value, counter_name, variant, test_model_params,
                                      ee_kpi_targets=None):
        kpi_structure = {
            'id': None,
            'value': round(value, 2),
            'source': 'EEKPI',
            'variant': {
                'smod': variant['smod'],
                'rmod': variant['rmod'],
                'rat': GenericReportEEKpi._get_rat_from_cells(variant['cell']),
                'object': variant['object'],
                'test_model': {
                    'cell': [],
                    'load': [],
                    'pmax': [],
                    'model': []
                }
            },
            'entity_id': variant['mrbts_id']
        }
        if variant.get('serial_number'):
            kpi_structure['variant']['serial_number'] = variant['serial_number']
        if variant.get('bbmod'):
            kpi_structure['variant']['bbmod'] = variant['bbmod']

        test_model_variant = kpi_structure['variant']['test_model']
        for record in test_model_params:
            for cell in variant['cell']:
                short_name = [cm['short_name'] for cm in self._all_cells_info
                              if cm[self._passed_cell_dn_type] == record['dist_name']][0]
                if cell == short_name:
                    if kpi_structure['id'] is None:
                        kpi_structure['id'] = self._get_kpi_id(counter_name, record.get('load_level_name'))

                    target = GenericReportEEKpi._get_kpi_target(ee_kpi_targets, counter_name,
                                                                record.get('load_level_name'))
                    if target and 'target' not in kpi_structure:
                        kpi_structure['target'] = target
                    if record.get('test_model') is not None:
                        test_model_variant['model'].append(record['test_model'])

                    test_model_variant['load'].append(record['load_type'])
                    test_model_variant['pmax'].append(record['p_max'])
                    test_model_variant['cell'].append(short_name)

                    break
        return kpi_structure


